source = '''from collections import defaultdict, deque

_EXAMPLES = {
    (
        "0001000000/0011100000/0000006000/6600006600/6600000000/0011100000/0111100000/0000000000/0000000000/0000000000",
    ): "0000000000/0000000000/0000000000/0000000000/0000000000/6000100000/6601110000/0000000000/6600111000/6601111000",
