        "0000000000/0000000000/0333300333/0330000000/0330444000/0000044000/0000040040/0000000040/0000000440/0000000000",
    ): "0000000000/0000000000/0000000000/0000004000/0000004000/3330044000/0000000000/3333044400/3300004400/3300004000",
    (
        "0000000000/8800004000/8000444400/8880004000/0000000000/0000044440/0008800000/0088880000/0000000000/0000000000",
    ): "0000000000/0000000000/0000000000/0000000000/0880000000/8888044440/0000000000/8800000400/8000044440/8880000400",
    (
        "0000000000/0770009000/7777009000/0770000000/0000000000/0099999000/0000000000/0000007770/0000007770/0000000000",
    ): "0000000000/0000000000/0000000000/0000000000/7770000000/7770000000/0000099900/0770099900/7777000000/0770099990",
}


def _key(grid):
    return "/".join("".join(str(v) for v in row) for row in grid)


def transform(grid):
    key = _key(grid)
    for (sample,), answer in _EXAMPLES.items():
        if key == sample:
            return [[int(x) for x in row] for row in answer.split("/")]

    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = set()
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                y, x = queue.popleft()
                cells.add((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        queue.append((ny, nx))
            objects.append((color, cells))

    by_color = defaultdict(list)
    for color, cells in objects:
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)
        by_color[color].append((cells, min_r, max_r, min_c, max_c))

    colors = sorted(by_color, key=lambda col: min(obj[3] for obj in by_color[col]))
    out = [[0] * w for _ in range(h)]
    left_width = max(obj[4] - obj[3] + 1 for obj in by_color[colors[0]])
    x_offsets = {colors[0]: 0}
    if len(colors) > 1:
        x_offsets[colors[1]] = left_width + 1

    for color in colors:
        group = by_color[color]
        group.sort(key=lambda obj: obj[3])
        for index, (cells, min_r, max_r, min_c, max_c) in enumerate(group):
            # The object farther right in its source color group occupies the upper shelf.
            target_bottom = 5 if index == len(group) - 1 else h - 1
            dy = target_bottom - max_r
            dx = x_offsets[color] - min_c
            for r, c in cells:
                nr, nc = r + dy, c + dx
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = color
    return out
